const complexValue=z=>typeof z==='number'?num(z):`${num(z?.re)}${Number(z?.im)<0?'':'+'}${num(z?.im)}i`;
export function pathwaysEvidence(record){
 const r=record.result;
 switch(record.action){
  case'band_rep_lab':return `SG${r.spaceGroup.number}；k=(${r.k.map(num).join(', ')}); number of sites =${r.site.positions.length}; Fiber dimension =${r.orbitDimension}; Decompose =${r.decomposition.terms.map(t=>`${t.multiplicity}×${t.dimension}dimension`).join(' + ')}${r.screw?.selectedEigenvalues?`; Spiral eigenvalue =${r.screw.selectedEigenvalues.map(complexValue).join(', ')}`:''}; indicates verification =${r.checks.passed?"passed":"needs verification"}; Band energy not calculated`;
  case'analyze':{const i=r.littleGroup.unitaryOperations.findIndex(op=>op.name==='C2z');return `SG${record.input.group_number??'—'}；k=(${record.input.k.map(num).join(', ')})；${record.input.doubleValued?"double value":"single value"}small group order =${r.littleGroup.order}; Irreducible dimension =${r.irreps.map(x=>x.dimension).join(', ')}${i>=0?`; C2z character =${r.irreps.map(x=>complexValue(x.characters[i])).join(', ')}`:''}; numerical value indicates verification =${r.validation.passed?"passed":"needs verification"}; Local D numbers cannot be directly matched across calculations`;}
  case'phonon_thermo':return `Source=${r.source}；${r.basisLabel}，n=${r.summary.natom}；3nR=${num(r.summary.dulongPetitLimit)} J/(mol K)；${r.series.map(s=>{const at=s.rows.find(x=>x.temperature===300);return `${s.id}：ZPE=${num(s.zeroPointEnergy)} kJ/mol${at?`，Cv(300K)=${num(at.heatCapacity)} J/(mol K)`:''}`;}).join('；')}; Heat capacity is different from single Q scattering intensity`;
  case'dynamic_scattering_lab':{const s=r.data.selection;return `Q=${num(s.Q)} Å⁻¹；q=${num(s.reducedRLU)}×2π/a；T=${num(r.parameters.temperature)} K；${s.groups.map(g=>`${g.label} ε=${num(g.energy)} meV，I+=${num(g.stokesWeight)}，I−=${num(g.antiStokesWeight)}${g.excluded?"(low energy excluded)":''}`).join('；')}; Detailed balance residual =${num(r.checks.detailedBalanceResidual)}; sample =${r.checks.gridResolved?"has met the current step size criterion":"requires encryption"}; relative to one phonon weight`;}
  case'domain_wall_lab':if(r.model==='landau')return `reduced domain wall width =${num(r.wall.width)}; Discrete wall energy =${num(r.wall.tension)}; Continuous wall energy =${num(r.wall.continuumTension)}; Balanced residual =${num(r.checks.stationaryResidual)}; No automatic mapping of electronic SSH parameters`;return `SSH limited chain =${r.parameters.sites}grid point; near zero energy subspace dimension =${r.chain.subspaceCount}; center weight =${num(r.summary.find(x=>x.label==="total weight of subspace center area")?.value)}; Endpoint weight =${num(r.summary.find(x=>x.label==="The total weight of the six grid points at both ends of the subspace")?.value)}; Chiral residual =${num(r.checks.chiralResidual)}; intrinsic residual =${num(r.checks.eigenResidual)}; Need to distinguish between terminal state and interface state`;
  case'hubbard_lab':return `fixed (N↑,N↓)=(${r.sector.nUp},${r.sector.nDown}); dimension =${r.sector.dimension}; average double occupation =${num(r.ground.averageDoubleOccupancy)}；⟨S²⟩=${num(r.ground.totalSpinSquared)}; neighbor ⟨S_i·S_j⟩=${num(r.ground.nearestSpinCorrelation)}；Δ_{ST}=${num(r.gaps.dimerSingletTriplet?.gap)} eV; charge increase and decrease gap =${num(r.gaps.chargeGap)} eV; finite cluster, non-Mott phase transition proof`;
  case'quantum_geometry_lab':return `${r.topology.kind}=${num(r.topology.value)}; clearance =${num(r.topology.analyticDirectGap)} eV; periodic bulk phase and finite chain spectrum must be calculated separately`;
  case'local_multiplet_lab':return `N=${r.parameters.electrons}；S=${r.ground.spins.join(', ')}；⟨S²⟩=${num(r.ground.S2)}; Five-track local model, not equal to two-station single-track space`;
  default:return null;
 }
}
